def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) == 0:
        raise Blocked("no community available")
    return statusCode == 200 and responseBody.get("code") == 0 and all(item.get("id") and item.get("name") for item in data) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    if statusCode != 200 or responseBody.get("code") != 0:
        return False
    data = responseBody.get("data") or {}
    if not isinstance(data, dict):
        return False
    if not data.get("accessToken") or not data.get("refreshToken"):
        return False
    user = data.get("user") or {}
    return bool(user.get("id")) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    if statusCode != 200 or responseBody.get("code") != 0:
        return False
    if responseBody.get("requestId") != globalParam.get("request"):
        return False
    data = responseBody.get("data") or {}
    cca = data.get("communityChangedAt")
    if not isinstance(cca, str) or len(cca) != 20:
        return False
    if cca[4] != "-" or cca[7] != "-" or cca[10] != "T":
        return False
    if cca[13] != ":" or cca[16] != ":" or cca[19] != "Z":
        return False
    digits = cca[0:4] + cca[5:7] + cca[8:10] + cca[11:13] + cca[14:16] + cca[17:19]
    for ch in digits:
        if ch < "0" or ch > "9":
            return False
    return True

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    if statusCode != 200 or responseBody.get("code") != 0:
        return False
    if not responseBody.get("requestId"):
        return False
    data = responseBody.get("data") or {}
    return data.get("id") == globalParam.get("a_id")

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data")
    return statusCode == 200 and responseBody.get("code") == 0 and isinstance(data, dict) and len(data) == 0 and bool(responseBody.get("requestId"))
